import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"VM Crate Restructure","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0027-vm-crate-restructure.md","filePath":"vendored/handl/project/adrs/0027-vm-crate-restructure.md"}`),a={name:`handl/project/adrs/0027-vm-crate-restructure.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="vm-crate-restructure" tabindex="-1">VM Crate Restructure <a class="header-anchor" href="#vm-crate-restructure" aria-label="Permalink to “VM Crate Restructure”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Superseded by <a href="./0040-vm-is-an-operation-not-a-subsystem.html">ADR 0040 — VM is an Operation, Not a Subsystem</a>.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The workspace currently mixes <code>handl-runtime-*</code> and <code>handl-plugin-vm-*</code> package and directory names. The <code>crates/vm*</code> directories contain packages named <code>handl-runtime*</code>, while the <code>crates/runtime*</code> directories also contain packages named <code>handl-runtime*</code>. The source and internal documentation already refer to the project as <code>handl-vm</code>, but the published package names do not match.</p><p>In addition, the current higher-level runtime crates (<code>runtime-sandbox</code>, <code>runtime-type</code>, <code>runtime-server</code>) are hard-coded to the canonical value representation and the canonical tree-walking evaluator. This makes it impossible to swap the VM backend or the value representation, which blocks future work on bytecode and JIT execution targets.</p><p>We need a crate layout that:</p><ul><li>is internally consistent,</li><li>keeps the VM abstraction generic over both value type and execution strategy,</li><li>supports multiple VM backends,</li><li>supports multiple value representations,</li><li>removes the overloaded and inconsistent <code>runtime</code> namespace.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>We will move the entire VM surface into an <code>handl-plugin-vm-*</code> namespace with a strict separation between the abstraction, value representations, backends, and product crates.</p><h3 id="crate-layout" tabindex="-1">Crate layout <a class="header-anchor" href="#crate-layout" aria-label="Permalink to “Crate layout”">​</a></h3><table tabindex="0"><thead><tr><th>Current crate / dir</th><th>New crate / dir</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>crates/vm</code> (<code>handl-runtime</code>)</td><td><code>crates/vm</code> (<code>handl-vm</code>)</td><td>Core VM traits: <code>Value</code>, <code>Host</code>, <code>Context</code>, <code>VirtualMachine</code>, <code>Eval</code>, <code>Operation</code>, <code>Error</code></td></tr><tr><td><code>crates/plugin-vm-common</code> (<code>handl-runtime-common</code>)</td><td><code>crates/plugin-vm-common</code> (<code>handl-plugin-vm-common</code>)</td><td>Generic host building blocks: <code>Module&lt;V&gt;</code>, <code>ModuleHost&lt;V&gt;</code>, adapters, combinators, mocks, middleware, sandbox helpers</td></tr><tr><td><code>crates/plugin-vm-canonical</code> (<code>handl-runtime-canonical</code>)</td><td><code>crates/plugin-vm-backend-rust-interpreter</code> (<code>handl-plugin-vm-backend-rust-interpreter</code>)</td><td>Canonical tree-walking interpreter implemented in Rust</td></tr><tr><td><code>crates/runtime</code> (<code>handl-runtime-values</code>)</td><td><code>crates/plugin-vm-values-json</code> (<code>handl-plugin-vm-values-json</code>)</td><td>JSON-backed value representation: <code>NonFunctionValue</code>, <code>FunctionValue</code>, <code>HostValue</code>, <code>Frontend</code></td></tr><tr><td><code>crates/runtime-config</code> (<code>handl-runtime-config</code>)</td><td>— delete —</td><td><code>CanonicalContext</code> and the concrete <code>Context</code> implementation move to <code>handl-plugin-vm-backend-rust-interpreter</code>; value types move to <code>handl-plugin-vm-values-json</code></td></tr><tr><td><code>crates/runtime-core</code> (<code>handl-runtime-modules</code>)</td><td>— delete —</td><td><code>Module</code> and <code>ModuleHost</code> move to <code>handl-plugin-vm-common</code></td></tr><tr><td><code>crates/runtime-sandbox</code> (<code>handl-runtime-sandbox</code>)</td><td><code>crates/plugin-vm-config</code> (<code>handl-plugin-vm-config</code>)</td><td>Generic, value-agnostic, pure configuration VM (defaults to <code>handl-plugin-vm-values-json</code> + <code>handl-plugin-vm-backend-rust-interpreter</code> behind a <code>canonical</code> feature)</td></tr><tr><td><code>crates/runtime-type</code> (<code>handl-runtime-type</code>)</td><td><code>crates/plugin-vm-type</code> (<code>handl-plugin-vm-type</code>)</td><td>Generic, value-agnostic type-as-values VM</td></tr><tr><td><code>crates/runtime-server</code> (<code>handl-runtime-server</code>)</td><td><code>crates/plugin-vm-server</code> (<code>handl-plugin-vm-server</code>)</td><td>Generic, value-agnostic server VM</td></tr><tr><td><em>new</em></td><td><code>crates/plugin-vm-transform</code> (<code>handl-plugin-vm-transform</code>)</td><td>Generic AST / expression transformation utilities</td></tr></tbody></table><h3 id="planned-future-crates" tabindex="-1">Planned future crates <a class="header-anchor" href="#planned-future-crates" aria-label="Permalink to “Planned future crates”">​</a></h3><table tabindex="0"><thead><tr><th>New crate</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>handl-plugin-vm-backend-bytecode</code></td><td>Bytecode compiler + interpreter VM</td></tr><tr><td><code>handl-plugin-vm-backend-jit</code></td><td>JIT compiled VM</td></tr><tr><td><code>handl-plugin-vm-values-*</code></td><td>Additional value representations as needed (e.g. compact, no-heap)</td></tr></tbody></table><h3 id="design-rules" tabindex="-1">Design rules <a class="header-anchor" href="#design-rules" aria-label="Permalink to “Design rules”">​</a></h3><ol><li><code>handl-vm</code> is the only abstraction crate. It defines <code>Value</code>, <code>Host</code>, <code>Context</code>, <code>VirtualMachine</code>, <code>Eval</code>, <code>Operation</code>, <code>Error</code>. It is generic over <code>V</code> and has no dependency on <code>serde_json</code>, the canonical AST, or any backend.</li><li><code>handl-plugin-vm-values-json</code> is one concrete <code>Value</code> implementation. It depends on <code>handl-vm</code> and <code>serde_json</code>.</li><li><code>handl-plugin-vm-backend-*</code> crates implement the <code>handl-vm</code> traits. They are allowed to be generic over <code>V</code> but may choose a default value representation (e.g. <code>handl-plugin-vm-values-json</code>) for convenience.</li><li><code>lib-*</code> modules become generic over <code>V: Value</code>. They may use <code>handl-plugin-vm-values-json</code> as their default test and production value, but they must not hard-code <code>NonFunctionValue</code>.</li><li><code>handl-plugin-vm-common</code> holds generic host-building blocks, including <code>Module&lt;V&gt;</code> and <code>ModuleHost&lt;V&gt;</code> (currently <code>handl-runtime-modules</code>).</li><li><code>handl-plugin-vm-config</code>, <code>handl-plugin-vm-type</code>, <code>handl-plugin-vm-server</code>, and <code>handl-plugin-vm-transform</code> are generic over <code>V: Value</code> and over the VM backend. They depend on <code>handl-vm</code> and <code>handl-plugin-vm-common</code>, not on a specific <code>handl-plugin-vm-backend-*</code> crate.</li><li>The <code>handl-runtime-*</code> package namespace is retired. The <code>runtime</code> and <code>runtime-*</code> directory names are retired.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Every <code>Cargo.toml</code> and <code>use</code> statement that refers to <code>handl-runtime*</code> must be updated.</li><li><code>crates/runtime</code> and <code>crates/runtime-core</code> and <code>crates/runtime-config</code> are removed from the workspace.</li><li><code>handl-plugin-vm-sandbox</code> no longer exists as a separate crate; its functionality either moves to <code>handl-plugin-vm-common</code> as a generic building block or becomes part of <code>handl-plugin-vm-config</code> as the default pure config VM.</li><li>The <code>lib-*</code> modules must be refactored to operate through the <code>Value</code> trait rather than <code>NonFunctionValue</code>-specific accessors.</li><li>Future <code>handl-plugin-vm-backend-bytecode</code> and <code>handl-plugin-vm-backend-jit</code> can be added without renaming or touching the abstraction or product crates.</li><li>Future <code>handl-plugin-vm-values-*</code> can be added without touching the VM core.</li><li>Consumers such as the <code>handl</code> CLI get a clear three-layer dependency: <code>handl-vm</code> (traits) + <code>handl-plugin-vm-values-json</code> (values) + <code>handl-plugin-vm-backend-rust-interpreter</code> (default backend), with the ability to substitute any layer.</li></ul><p>(See status at top of document.)</p>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};